// Family portrait options, shared by the customer form, the save route and the admin view.
// The option list itself is generated by scripts/build-portrait-catalog.cjs.
import raw from "./catalog.json";

export type Option = {
  id: string;
  file: string;
  code?: string;
  label?: string;
  kind?: string;
  style?: string;
  colour?: string;
  fileArmOut?: string;
};
export type HumanType = "Man" | "Woman" | "Boy" | "Girl" | "Baby";
export type PetType = "Dog" | "Cat";
export type MemberType = HumanType | PetType;

type PersonOptions = { hair: Option[]; tops: Option[]; bottoms: Option[]; dresses: Option[]; ribbons?: Option[] };
type Catalog = {
  builtAt: string;
  skins: { code: string; hex: string }[];
  people: Record<HumanType, PersonOptions>;
  bodies: Record<HumanType, { first?: string[]; other: string[] }>;
  pets: Record<PetType, { breed: string; variants: Option[] }[]>;
};

export const catalog = raw as Catalog;

export const HUMANS: HumanType[] = ["Man", "Woman", "Boy", "Girl", "Baby"];
export const PETS: PetType[] = ["Dog", "Cat"];
export const isPet = (t: MemberType): t is PetType => t === "Dog" || t === "Cat";
export const isAdult = (t: MemberType) => t === "Man" || t === "Woman";

// Hair colour names in the order customers see them, with a swatch colour
export const HAIR_COLOURS: [string, string][] = [
  ["Black", "#141414"], ["Soft Black", "#3a3634"], ["Dark Brown", "#3b1f14"], ["Brown", "#6b4330"],
  ["Light Brown", "#97786a"], ["Auburn", "#8a3d1c"], ["Burgundy", "#6a2b33"], ["Ginger", "#c9733f"],
  ["Golden Blonde", "#c9a564"], ["Blonde", "#d9c48f"], ["Ash Blonde", "#bfae94"], ["Grey", "#8d8d90"],
  ["Silver", "#d7d7d9"], ["Red", "#c0282d"], ["Pink", "#e48fb4"], ["Purple", "#7d4fa8"],
  ["Blue", "#3f6fc4"], ["Green", "#3f9a6d"], ["Ombré", "linear-gradient(#3b1f14,#d8c08a)"],
];

export const SIZES = [
  { label: "2–4", min: 2, max: 4 },
  { label: "5–6", min: 5, max: 6 },
  { label: "7–8", min: 7, max: 8 },
] as const;

export const thumb = (o: { id: string }) => `/portrait/${o.id}.webp`;

// What the customer picked for one person or pet (ids point into the catalog)
export type Member = {
  type: MemberType;
  name?: string;
  skin?: string; // S1–S4
  hair?: string;
  outfit?: "separates" | "dress";
  top?: string;
  bottom?: string;
  dress?: string;
  ribbon?: string;
  pet?: string;
};

export type PortraitSubmission = { title?: string; notes?: string; members: Member[] };

const byId = new Map<string, Option>();
for (const p of Object.values(catalog.people)) {
  for (const list of [p.hair, p.tops, p.bottoms, p.dresses, p.ribbons ?? []]) for (const o of list) byId.set(o.id, o);
}
for (const groups of Object.values(catalog.pets)) for (const g of groups) for (const v of g.variants) byId.set(v.id, { ...v, label: v.label ?? g.breed });
export const optionById = (id?: string) => (id ? byId.get(id) : undefined);

/** Which parts this person still needs before they can be saved. */
export function missingParts(m: Member): string[] {
  if (isPet(m.type)) return m.pet ? [] : ["breed and colour"];
  const p = catalog.people[m.type];
  const miss: string[] = [];
  if (!m.skin) miss.push("skin tone");
  if (!m.hair) miss.push("hair");
  if (m.type === "Baby") { if (!m.top) miss.push("babygrow"); return miss; }
  if (m.outfit === "dress" && p.dresses.length) { if (!m.dress) miss.push("dress"); }
  else { if (!m.top) miss.push("top"); if (!m.bottom) miss.push("jeans"); }
  return miss;
}

/** Check a picked id belongs to the right list for this person type. */
function inList(list: Option[] | undefined, id?: string) {
  return !id || !!list?.some((o) => o.id === id);
}
export function validMember(m: Member): boolean {
  if (![...HUMANS, ...PETS].includes(m.type)) return false;
  if (isPet(m.type)) return !!m.pet && catalog.pets[m.type].some((g) => g.variants.some((v) => v.id === m.pet));
  const p = catalog.people[m.type];
  if (m.skin && !catalog.skins.some((s) => s.code === m.skin)) return false;
  return inList(p.hair, m.hair) && inList(p.tops, m.top) && inList(p.bottoms, m.bottom) && inList(p.dresses, m.dress) && inList(p.ribbons, m.ribbon)
    && missingParts(m).length === 0;
}

export type ResolvedPart = { part: string; label: string; code?: string; file: string; thumbId?: string };
export type ResolvedMember = { position: number; type: MemberType; name?: string; summary: string; parts: ResolvedPart[] };

/** Turn picks into exact Drive files. Position matters: the 1st adult uses the arm-out pose. */
export function resolve(sub: PortraitSubmission): ResolvedMember[] {
  let adultsSeen = 0;
  return sub.members.map((m, i) => {
    const parts: ResolvedPart[] = [];
    const add = (part: string, o?: Option, file?: string) => {
      if (o) parts.push({ part, label: o.label ?? o.style ?? part, code: o.code, file: file ?? o.file, thumbId: o.id });
    };
    if (isPet(m.type)) {
      add(m.type, optionById(m.pet));
    } else {
      const first = isAdult(m.type) && adultsSeen++ === 0;
      const bodies = catalog.bodies[m.type];
      const skinIdx = Math.max(0, catalog.skins.findIndex((s) => s.code === m.skin));
      const bodyFile = (first && bodies.first ? bodies.first : bodies.other)[skinIdx];
      parts.push({ part: "Body", label: `${m.skin ?? "S1"} skin${first ? " · 1st adult pose" : ""}`, code: m.skin, file: bodyFile });
      const hair = optionById(m.hair);
      if (hair) parts.push({ part: "Hair", label: `${hair.colour} · ${hair.style}`, file: hair.file, thumbId: hair.id });
      if (m.outfit === "dress") add("Dress", optionById(m.dress));
      else {
        const top = optionById(m.top);
        add("Top", top, first && top?.fileArmOut ? top.fileArmOut : undefined);
        add("Bottoms", optionById(m.bottom));
      }
      add("Ribbon", optionById(m.ribbon));
    }
    const summary = parts.filter((p) => p.part !== "Body").map((p) => p.code ? `${p.part} ${p.code}` : p.label).join(", ");
    return { position: i + 1, type: m.type, name: m.name?.trim() || undefined, summary, parts };
  });
}

/** Plain-text version for the log and the notification email. */
export function portraitText(sub: PortraitSubmission, sizeLabel?: string | null): string {
  const lines = resolve(sub).map((r) =>
    `${r.position}. ${r.type}${r.name ? ` (${r.name})` : ""}: ${r.parts.map((p) => p.code ? `${p.part} ${p.code}` : `${p.part}: ${p.label}`).join(", ")}`);
  return [
    sub.title ? `Title: ${sub.title}` : null,
    `People & pets: ${sub.members.length}${sizeLabel ? ` (paid for ${sizeLabel})` : ""}`,
    ...lines,
    sub.notes ? `Notes: ${sub.notes}` : null,
  ].filter(Boolean).join("\n");
}
